require "yaml"
require "prism"
require "pathname"

module DeckplateBuild
  # Builds config/deckplate/components.yml: the catalogue of every component, read from the code (constructor, Variants declarations, slots,
  # doc comment, templates, stylesheets, previews) so that it cannot drift. Needs the Rails environment (the dummy app); see bin/build-manifest.
  # Dev-only: the generated file ships in the gem, this builder does not.
  class ManifestBuilder
    PATH = "config/deckplate/components.yml".freeze
    STYLES = "app/assets/stylesheets/deckplate".freeze
    CONTROLLERS = "app/javascript/deckplate/controllers".freeze
    ABSTRACT = %w[Deckplate::Forms::ControlComponent].freeze
    HEADER = "# Generated by bin/build-manifest from the component classes, templates and stylesheets. Do not edit.\n".freeze
    HTML_OPTIONS = "Extra keyword arguments become attributes of the component's element: class (appended), data and aria (merged; controller, action and " \
                   "describedby are concatenated), style (appended), id and any other attribute (the caller wins). Form controls send them to the native " \
                   "control, not to the wrapper. Components that accept them have html_options: true.".freeze

    def initialize(root)
      @root = Pathname(root)
    end

    def yaml = "#{HEADER}#{YAML.dump(document)}"

    def write! = @root.join(PATH).write(yaml)

    private

    def document
      { "format" => 1,
        "common" => { "html_options" => HTML_OPTIONS, "colors" => Deckplate::Concerns::Colorable::ROLES.map(&:to_s) },
        "components" => classes.to_h { [ key(_1), entry(_1) ] }.sort.to_h }
    end

    # The gem's own components (test doubles defined by the specs are not part of the catalogue)
    def classes
      own = @root.join("app/components").to_s
      Deckplate::BaseComponent.descendants.select { _1.name && Object.const_source_location(_1.name).to_a.first.to_s.start_with?(own) }.sort_by(&:name)
    end

    # Deckplate::Forms::TextInputComponent -> "Forms::TextInput"
    def key(klass) = klass.name.delete_prefix("Deckplate::").delete_suffix("Component")

    def entry(klass)
      abstract = ABSTRACT.include?(klass.name)
      parent = klass.superclass
      slot = slot_of[klass.name]
      stylesheet = (stylesheet_for(klass) unless abstract) # nil for a component that reuses the classes of another one (form controls, slot parts)
      {
        "class" => klass.name,
        "description" => description(klass),
        "abstract" => (true if abstract),
        "extends" => (key(parent) unless parent == Deckplate::BaseComponent),
        "sheet" => sheet_of(klass),
        "css_block" => (klass.block_name if stylesheet),
        "stylesheet" => stylesheet,
        "controllers" => attached_controllers(klass).presence,
        "talks_to" => (action_targets(klass) - attached_controllers(klass)).presence,
        "html_options" => (true if keyrest?(klass.instance_method(:initialize))),
        "params" => params(klass.instance_method(:initialize), klass).presence,
        "slots" => slots(klass).presence,
        "slot_of" => slot&.sort,
        "previews" => previews(klass).presence
      }.compact
    end

    # ---- documentation: the comment block right above the class

    def description(klass)
      file, line = Object.const_source_location(klass.name)
      comments = parse(file).comments.select { _1.location.end_line < line }.sort_by { _1.location.start_line }
      block = []
      expected = line - 1
      comments.reverse_each do |comment|
        break unless comment.location.end_line == expected

        block.unshift(comment.slice.sub(/\A#\s?/, ""))
        expected = comment.location.start_line - 1
      end
      block.join(" ").strip
    end

    # ---- parameters: names and kinds from reflection, defaults from the source (Prism)

    def keyrest?(method) = method.parameters.any? { |kind, _| kind == :keyrest }

    def params(method, klass)
      defaults = default_sources(method)
      method.parameters.reject { |kind, _| kind == :keyrest || kind == :block }.to_h do |kind, name|
        variant = klass.respond_to?(:variant_definitions) ? klass.variant_definitions[name] : nil
        [ name.to_s, param_entry(kind == :keyreq, defaults[name], variant) ]
      end
    end

    def param_entry(required, default, variant)
      info = variant && { "variant" => { "values" => variant[:values].map(&:to_s), "default" => variant[:default].to_s } }
      return { "required" => true }.merge(info || {}) if required
      return { "required" => false }.merge(info) if info

      { "required" => false, "default" => default }.compact
    end

    # { name => "source of the default" } for the optional keyword parameters of a method or lambda
    def default_sources(callable)
      file, line = callable.source_location
      node = find_node(parse(file).value, line) or return {}
      list = node.parameters
      list = list.parameters if list.is_a?(Prism::BlockParametersNode) # a lambda wraps its parameters
      keywords = list&.keywords || []
      keywords.grep(Prism::OptionalKeywordParameterNode).to_h { [ _1.name, _1.value.slice ] }
    end

    # The def or lambda that starts on this line
    def find_node(tree, line)
      queue = [ tree ]
      until queue.empty?
        node = queue.shift
        return node if (node.is_a?(Prism::DefNode) || node.is_a?(Prism::LambdaNode)) && node.location.start_line == line

        queue.concat(node.compact_child_nodes)
      end
    end

    # ---- slots

    def slots(klass)
      klass.registered_slots.to_h do |name, slot|
        info = { "many" => (slot[:collection] ? true : false) }
        if (function = slot[:renderable_function])
          list = params(function, klass).presence
          info["params"] = list if list
        end
        component = slot_component(klass, slot)
        info["component"] = key(component) if component
        [ name.to_s, info ]
      end
    end

    def slot_component(klass, slot)
      given = slot[:renderable_class] || slot[:renderable_class_name]
      return unless given

      given.is_a?(Class) ? given : klass.module_parents.each { |scope| (return scope.const_get(given)) if scope.const_defined?(given, false) } && nil
    end

    # { "Deckplate::MenuItemComponent" => ["Menu"] }
    def slot_of
      @slot_of ||= classes.each_with_object(Hash.new { |h, k| h[k] = [] }) do |klass, map|
        klass.registered_slots.each_value { |slot| (c = slot_component(klass, slot)) && map[c.name] << key(klass) }
      end.transform_values(&:uniq)
    end

    # ---- Stimulus controllers: those the component attaches to its own element, and those whose actions it calls on an ancestor

    def attached_controllers(klass)
      known_controllers & sources(klass).scan(/controller(?::\s*|=)["']([^"']+)["']/).flatten.flat_map(&:split)
    end

    def action_targets(klass)
      known_controllers & sources(klass).scan(/(dp-[a-z-]+)#/).flatten
    end

    def sources(klass)
      file, = Object.const_source_location(klass.name)
      [ file, file.sub(/\.rb\z/, ".html.erb") ].select { File.exist?(_1) }.map { File.read(_1) }.join("\n")
    end

    def known_controllers
      @known_controllers ||= Dir[@root.join(CONTROLLERS, "dp_*_controller.js")].map { "dp-#{File.basename(_1)[/dp_(.*)_controller/, 1].tr('_', '-')}" }
    end

    # ---- stylesheets: the file that styles the component's block, and the shipped sheet it belongs to

    def stylesheet_for(klass)
      selector = /\.#{Regexp.escape(klass.block_name)}(?![a-z0-9-])/
      files = Dir[@root.join(STYLES, "**/*.css")].sort.select { File.read(_1).match?(selector) }
      return if files.empty?

      own = files.find { File.basename(_1, ".css") == klass.block_name.delete_prefix("dp-") } || files.first
      Pathname(own).relative_path_from(@root).to_s
    end

    # The shipped stylesheet that carries the component's styles (ADR 0012): shapes and layout are in the core, the rest by family
    def sheet_of(klass)
      case klass.name.delete_prefix("Deckplate::")
      when /\AForms::/ then "forms"
      when /\AData::/ then "data"
      when /\AFeedback::/ then "feedback"
      when /\A(Shapes|Layout)::/ then "core"
      else "controls"
      end
    end

    # ---- Lookbook previews named after the component

    def previews(klass)
      slug = klass.name.demodulize.delete_suffix("Component").underscore
      ViewComponent::Preview.all.select { _1.preview_name == slug }.flat_map { |p| p.examples.map { |example| "#{p.preview_name}/#{example}" } }
    end

    def parse(file) = (@parsed ||= {})[file] ||= Prism.parse_file(file)
  end
end
